import json,re,glob
for fn in sorted(glob.glob('articles/2026/06/*/articles.jsonl')):
  day=fn.split('/')[-2]
  if int(day)<22: continue
  with open(fn) as f:
    for line in f:
      a=json.loads(line)
      txt=(a.get('title','')+' '+a.get('content',''))
      if re.search(r'Gwangju|Honam',txt,re.I) and re.search(r'semiconductor|chip|packag',txt,re.I):
        print('\\nDATE',day,'TITLE',a.get('title'))
        ss=re.split(r'(?<=[."'!?])'"\\s+',a.get('content',''))
        for i,s in enumerate(ss):
          if re.search(r'Gwangju|Honam|packag',s,re.I):
            print(' '.join(ss[max(0,i-1):min(len(ss),i+2)]))
PY"

